        asld
        asld
        asld
        bcs     PTU_CheckMAPThresholdsForLock
        cmpa    >PTUMSP_PTUMinLockSpeed              ; PTUMSP: Min Speed for PTU lock
        bcc     PTU_CheckMAPThresholdsForLock
